INSERT INTO grammar_points
  (id, language_id, slug, title, pattern, level_id, category, register, meaning_short, meaning_long, nuance, status, published, sort_index) VALUES
  ('gp-no-pronoun', 'lang-ja', 'no-pronoun', 'の (one)', 'Adjective + の', 'lvl-ja-n5', 'particle', 'casual', 'Stands in for a noun already understood.', '赤いのをください, "the red one please". 大きいのが好きです.', 'A な-adjective takes な before it: 静かなの. Without the の the sentence would name a colour rather than a thing.', 'in-review', true, 550),
  ('gp-modifying-clause', 'lang-ja', 'modifying-clause', 'Relative clause', 'Plain form + Noun', 'lvl-ja-n5', 'construction', 'casual', 'A clause describing a noun.', '私が買った本, "the book I bought". 日本語を話す人.', 'The clause always comes BEFORE the noun and nothing marks the join — no "that", no "which". The subject inside it usually takes が rather than は.', 'in-review', true, 551),
  ('gp-te-negative', 'lang-ja', 'te-negative', '〜ないで', 'Verb-ない + で', 'lvl-ja-n5', 'construction', 'casual', 'Without doing, or instead of doing.', '朝ごはんを食べないで学校に行きました.', 'Distinct from 〜なくて, which gives a reason: 分からなくて困った is "I was stuck because I didn''t understand".', 'in-review', true, 552),
  ('gp-nakute', 'lang-ja', 'nakute', '〜なくて', 'Verb-ない stem + くて', 'lvl-ja-n5', 'construction', 'casual', 'Not, and so — a negative reason.', '時間がなくて行けませんでした.', 'ないで is manner, なくて is cause. Both are negatives joined to what follows, and the difference is what the join means.', 'in-review', true, 553),
  ('gp-te-adjective', 'lang-ja', 'te-adjective', 'Adjective linking', 'iAdj → 〜くて / naAdj → 〜で', 'lvl-ja-n5', 'construction', 'casual', 'And — joining adjectives.', '安くておいしい. 静かできれいな部屋.', 'Both must lean the same way. Joining a good and a bad point needs が or けど, not くて.', 'in-review', true, 554),
  ('gp-ga-desire', 'lang-ja', 'ga-desire', 'が with feelings', 'Noun + が + 好き / ほしい / 上手', 'lvl-ja-n5', 'particle', 'casual', 'Marks the object of a feeling or ability.', '猫が好きです. 日本語が分かります.', 'These are states, not actions, so the thing is a subject rather than an object. 好き is an adjective, which is why を would be wrong.', 'in-review', true, 555),
  ('gp-wakaru', 'lang-ja', 'wakaru', '分かる / できる', 'Noun + が + 分かる', 'lvl-ja-n5', 'expression', 'casual', 'Understand / be able to.', '日本語が分かります. 料理ができます.', 'Both are intransitive and take が. 分かる is closer to "becomes clear to me" than to "I understand", which is why the grammar puts the thing in the subject.', 'in-review', true, 556),
  ('gp-aru-iru-possession', 'lang-ja', 'aru-iru-possession', 'Having something', 'Noun + が + あります / います', 'lvl-ja-n5', 'expression', 'polite', 'Have.', '時間がありますか。子どもが二人います。', 'Japanese has no verb "to have" — possession is existence. Whether it is ある or いる still follows animacy.', 'in-review', true, 557),
  ('gp-nan-desu-ka', 'lang-ja', 'nan-desu-ka', '何ですか', 'これは + 何ですか', 'lvl-ja-n5', 'expression', 'polite', 'What is it?', 'これは何ですか. 何 is read なん before です, だ, の and counters.', 'なに and なん are the same word; the reading shifts to whatever is easier to say next, which is why it changes before a counter.', 'in-review', true, 558),
  ('gp-koto-ga-dekiru-n5', 'lang-ja', 'dekiru-n5', '〜ことができます', 'Plain present + ことができます', 'lvl-ja-n5', 'expression', 'polite', 'Can do.', '日本語を話すことができます.', 'The N5 way to say "can", before the potential form arrives at N4. Longer, and it keeps を where the potential prefers が.', 'in-review', true, 559),
  ('gp-mou-sugu', 'lang-ja', 'mou-sugu', 'もうすぐ / これから', 'もうすぐ + Verb', 'lvl-ja-n5', 'adverb', 'casual', 'Soon / from now on.', 'もうすぐ着きます. これから勉強します.', 'これから marks a turning point rather than a time — it is "starting now", with the implication that things were different before.', 'in-review', true, 560),
  ('gp-tokoro-place', 'lang-ja', 'toki-doki-place', '〜の中 / 上 / 下 / 前 / 後ろ', 'Noun + の + 上', 'lvl-ja-n5', 'construction', 'casual', 'Position words.', '机の上, 家の前, かばんの中.', 'These are nouns, not prepositions, which is why they need の and why they come AFTER the thing they locate.', 'in-review', true, 561),
  ('gp-to-quotation', 'lang-ja', 'to-quotation', 'と (quotation)', 'Clause + と + 言う', 'lvl-ja-n5', 'particle', 'casual', 'Marks reported speech or thought.', '「行きます」と言いました. 高いと思います.', 'The clause before と stays plain even in a polite sentence — politeness belongs to the outer verb, not the quoted words.', 'in-review', true, 562),
  ('gp-imasu-teiru-state', 'lang-ja', 'teiru-habit', '〜ている (habit)', 'Verb-て + いる', 'lvl-ja-n5', 'construction', 'casual', 'A repeated action, not just an ongoing one.', '毎日走っています. 銀行で働いています.', 'A third reading beside "in progress" and "resulting state". Which one applies is decided by the verb and the adverbs around it.', 'in-review', true, 563),
  ('gp-mada-teimasen', 'lang-ja', 'mada-teimasen', 'まだ〜ていません', 'まだ + Verb-て + いません', 'lvl-ja-n5', 'expression', 'polite', 'Haven''t done it yet.', 'まだ食べていません.', 'まだ食べません would be a refusal about the future. The ていません is what makes it "not yet" rather than "not going to".', 'in-review', true, 564),
  ('gp-tsukau-de-tool', 'lang-ja', 'de-tool', 'で (tool, material)', 'Noun + で', 'lvl-ja-n5', 'particle', 'casual', 'With, by, out of.', 'はしで食べます. 木で作ります. バスで行きます.', 'One particle covers instrument, material and means of transport — all three answer "by what".', 'in-review', true, 565),
  ('gp-to-together', 'lang-ja', 'to-together-n5', 'と (together with)', 'Person + と', 'lvl-ja-n5', 'particle', 'casual', 'With someone.', '友だちと行きます.', 'と is exhaustive between nouns — りんごとみかん is those two and nothing else. や leaves the list open.', 'in-review', true, 566),
  ('gp-ka-or', 'lang-ja', 'ka-or', 'か (or)', 'Noun + か + Noun', 'lvl-ja-n5', 'particle', 'casual', 'Or.', 'コーヒーかお茶を飲みます.', 'The same か as the question particle. Offering alternatives and asking a question are one idea in Japanese.', 'in-review', true, 567),
  ('gp-onaji', 'lang-ja', 'onaji', '同じ', '同じ + Noun', 'lvl-ja-n5', 'expression', 'casual', 'The same.', '同じ本を読みました. AとBは同じです.', '同じ takes no な before a noun, unlike every other adjective shaped like it. It simply does not, and the exam tests it.', 'in-review', true, 568),
  ('gp-imperative-nasai', 'lang-ja', 'nasai', '〜なさい', 'Verb stem + なさい', 'lvl-ja-n5', 'expression', 'casual', 'Do it — a gentle order.', '早く寝なさい.', 'From a parent or teacher downward. It is softer than the bare imperative and impossible upward.', 'in-review', true, 569),
  ('gp-douzo-doumo', 'lang-ja', 'douzo-doumo', 'どうぞ / どうも', 'どうぞ + Clause', 'lvl-ja-n5', 'expression', 'polite', 'Please, here you are / thanks.', 'どうぞお入りください. どうもありがとう.', 'Both are so vague that they carry almost any meaning the situation supplies — どうも alone is a greeting, a thanks and an apology.', 'in-review', true, 570),
  ('gp-ohayou-set', 'lang-ja', 'greetings', 'Greetings', 'おはよう / こんにちは / こんばんは', 'lvl-ja-n5', 'expression', 'polite', 'Set greetings by time of day.', 'おはようございます before about ten, こんにちは through the day, こんばんは after dark.', 'こんにちは and こんばんは end in は because they are the topic particle — each is half of a dropped sentence about today or tonight.', 'in-review', true, 571),
  ('gp-itadakimasu', 'lang-ja', 'itadakimasu', 'いただきます / ごちそうさま', 'Set phrase', 'lvl-ja-n5', 'expression', 'polite', 'Before and after eating.', 'いただきます, then ごちそうさまでした.', 'いただく is the humble form of "receive": you are receiving the meal, not merely starting it. ごちそう is a feast, and 馳走 originally meant running about to prepare one.', 'in-review', true, 572),
  ('gp-sumimasen', 'lang-ja', 'sumimasen', 'すみません', 'Set phrase', 'lvl-ja-n5', 'expression', 'polite', 'Excuse me, sorry, and thank you.', 'すみません、駅はどこですか.', 'From 済む, "to be settled" — the negative says the matter is not yet settled between us. That is why it thanks as well as apologises.', 'in-review', true, 573),
  ('gp-onegaishimasu', 'lang-ja', 'onegaishimasu', 'お願いします', 'Noun + をお願いします', 'lvl-ja-n5', 'expression', 'polite', 'Please, I''d like.', 'コーヒーをお願いします.', 'The most useful request in the language: a noun and this phrase will order, ask and book almost anything.', 'in-review', true, 574),
  ('gp-dake-n5b', 'lang-ja', 'te-form-request-chain', '〜て、〜て', 'Verb-て + Verb-て + Verb', 'lvl-ja-n5', 'construction', 'casual', 'And then — a sequence of actions.', '起きて、朝ごはんを食べて、学校に行きます.', 'Only the final verb carries the tense and politeness. A chain five verbs long is still one sentence, decided entirely by how it ends.', 'in-review', true, 575),
  ('gp-ga-subject-clause', 'lang-ja', 'ga-in-clause', 'が inside a clause', 'Clause with が + Noun', 'lvl-ja-n5', 'particle', 'casual', 'The subject of a describing clause.', '私が作ったケーキ. 背が高い人.', 'は cannot appear inside a relative clause, because a topic belongs to the whole sentence and a clause is only part of one.', 'in-review', true, 576),
  ('gp-desu-ka-confirm', 'lang-ja', 'sou-desu-ka', 'そうですか / そうですね', 'Set phrase', 'lvl-ja-n5', 'expression', 'polite', 'Is that so / let me see.', 'そうですか. そうですね…', 'Intonation carries the whole meaning of そうですか: falling is "I see", rising is genuine surprise. そうですね buys thinking time.', 'in-review', true, 577),
  ('gp-mo-mo', 'lang-ja', 'mo-mo', '〜も〜も', 'Noun + も + Noun + も', 'lvl-ja-n5', 'particle', 'casual', 'Both — or, with a negative, neither.', '肉も魚も好きです. 肉も魚も食べません.', 'The same pair swings from "both" to "neither" on the verb alone, which is why the ending has to be heard out.', 'in-review', true, 578),
  ('gp-ka-dou-n5', 'lang-ja', 'nani-ka', '何か / だれか / どこか', 'Question word + か', 'lvl-ja-n5', 'construction', 'casual', 'Something, someone, somewhere.', '何か食べましたか. だれかいますか.', 'The particle after them is usually dropped: 何か食べる, not 何かを食べる.', 'in-review', true, 579),
  ('gp-nani-mo', 'lang-ja', 'nani-mo', '何も / だれも / どこも', 'Question word + も + negative', 'lvl-ja-n5', 'construction', 'casual', 'Nothing, nobody, nowhere.', '何も食べませんでした. だれも来ませんでした.', 'These demand a negative verb. か is some, も is none — one particle decides the quantity.', 'in-review', true, 580),
  ('gp-ni-purpose', 'lang-ja', 'ni-purpose', 'に (purpose of going)', 'Verb stem + に + 行く / 来る', 'lvl-ja-n5', 'construction', 'casual', 'Go somewhere in order to do something.', '映画を見に行きます. 昼ごはんを食べに来ました.', 'Only with verbs of motion. The stem carries the purpose and the motion verb carries the tense.', 'in-review', true, 581),
  ('gp-sentence-order', 'lang-ja', 'word-order', 'Word order', 'Topic + Time + Place + Object + Verb', 'lvl-ja-n5', 'construction', 'casual', 'The verb goes last.', '私は明日図書館で本を読みます.', 'Everything before the verb can be reordered, because the particles say what each phrase is doing. What cannot move is the verb.', 'in-review', true, 582),
  ('gp-topic-drop', 'lang-ja', 'subject-drop', 'Leaving things out', 'Omitted subject / object', 'lvl-ja-n5', 'construction', 'casual', 'Anything understood is dropped.', '（私は）学生です. 「食べましたか」「はい、食べました」', 'Not laziness but the norm: repeating 私は every sentence sounds insistent, as if contrasting yourself with someone else.', 'in-review', true, 583)
